import audioJson from './audio.json';
import creditsJson from './audio-credits.json';

// Listening examples (Hörbeispiele): audio.json (hand-written: Commons file, work, performer) +
// audio-credits.json (generated by scripts/fetch-audio.mjs: stream URLs, length, licence).
// The files are streamed from upload.wikimedia.org, not copied into the app.
interface Clip { file: string; title: string; composer: string; performer?: string; start?: number }
interface Credit { mp3?: string; ogg?: string; seconds: number; author: string; licence: string; page: string }

const CLIPS = audioJson as Record<string, Clip>;
const CREDITS = creditsJson as Record<string, Credit>;

export interface AudioView {
  key: string;
  title: string; // the work
  composer: string;
  performer: string;
  sources: { src: string; type: string }[]; // mp3 first (Safari), ogg as fallback
  start: number; // seconds: where the interesting part begins
  seconds: number;
  credit: string;
  page: string;
}

export const hasAudio = (key: string) => key in CLIPS && key in CREDITS && !!(CREDITS[key].mp3 || CREDITS[key].ogg);
export const audioKeys = () => Object.keys(CLIPS);

export function audioView(key: string): AudioView | null {
  const a = CLIPS[key];
  const c = CREDITS[key];
  if (!a || !c || !(c.mp3 || c.ogg)) return null;
  const pd = /^(public domain|pd|cc0)/i.test(c.licence);
  // The Commons "author" is often just the composer again: then only the licence is named.
  const last = a.composer.split(' ').pop() ?? '';
  const who = a.performer || (c.author !== 'unbekannt' && !(last && c.author.includes(last)) ? c.author : '');
  return {
    key,
    title: a.title,
    composer: a.composer,
    performer: a.performer ?? '',
    sources: [
      ...(c.mp3 ? [{ src: c.mp3, type: 'audio/mpeg' }] : []),
      ...(c.ogg ? [{ src: c.ogg, type: 'audio/ogg' }] : []),
    ],
    start: a.start ?? 0,
    seconds: c.seconds,
    credit: pd ? `${who ? `${who} · ` : ''}Gemeinfrei · Wikimedia Commons` : `Aufnahme: ${who ? `${who}, ` : ''}${c.licence} · Wikimedia Commons`,
    page: c.page,
  };
}
